package com.vandorlabs.programmer;
import com.google.gson.*;
import io.netty.buffer.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Released operation indices, canonical bodies and malformed length handling, without gameplay mutation. */
public final class ProgrammerWireLegacyChecks {
 private static final JsonArray CASES=new JsonArray();
 private static Object field(ProgrammerMessage message,String name)throws Exception{java.lang.reflect.Field field=ProgrammerMessage.class.getDeclaredField(name);field.setAccessible(true);return field.get(message);}
 private static String hex(byte[] bytes){char[] result=new char[bytes.length*2],digits="0123456789abcdef".toCharArray();for(int i=0;i<bytes.length;i++){result[i*2]=digits[(bytes[i]&255)>>4];result[i*2+1]=digits[bytes[i]&15];}return new String(result);}
 private static byte[] bytes(ProgrammerMessage message){ByteBuf buffer=Unpooled.buffer();try{message.toBytes(buffer);byte[] result=new byte[buffer.readableBytes()];buffer.readBytes(result);return result;}finally{buffer.release();}}
 private static void profile(String name,byte[] wire)throws Exception{ProgrammerMessage decoded=new ProgrammerMessage();ByteBuf buffer=Unpooled.wrappedBuffer(wire);try{decoded.fromBytes(buffer);}finally{buffer.release();}JsonObject row=new JsonObject();row.addProperty("name",name);row.addProperty("wire",hex(wire));row.addProperty("valid",decoded.decodedValid());if(decoded.decodedValid()){row.addProperty("window",(Integer)field(decoded,"window"));row.addProperty("operation",(Integer)field(decoded,"operation"));row.addProperty("journal",(Boolean)field(decoded,"journal"));row.addProperty("title",(String)field(decoded,"title"));JsonArray pages=new JsonArray();for(String page:(String[])field(decoded,"pages"))pages.add(page);row.add("pages",pages);row.addProperty("canonical",hex(bytes(decoded)));}CASES.add(row);}
 private static byte[] textBody(int declared,String text,boolean page){ByteBuf b=Unpooled.buffer();try{b.writeInt(19);b.writeByte(0);b.writeBoolean(true);if(page)b.writeShort(0);b.writeShort(declared);b.writeBytes(text.getBytes(StandardCharsets.UTF_8));for(int i=page?1:0;i<8;i++)b.writeShort(0);byte[] result=new byte[b.readableBytes()];b.readBytes(result);return result;}finally{b.release();}}
 public static void main(String[] args)throws Exception{for(int window:new int[]{0,1,-1,32767,Integer.MAX_VALUE})for(int operation=0;operation<=4;operation++)for(boolean journal:new boolean[]{false,true})for(int pattern=0;pattern<5;pattern++){String title=pattern==0?"":pattern==1?"Source draft":pattern==2?"Δ🚀\u0000\r\n":pattern==3?String.join("",Collections.nCopies(100,"x")):null;String[] pages=new String[8];for(int i=0;i<8;i++)pages[i]=pattern==0?"":pattern==1?"Entry "+i+"\nNext\tcolumn":pattern==2?"漢字 🚀\u0000 "+i:pattern==3?String.join("",Collections.nCopies(700,"y")):null;ProgrammerMessage message=operation<2?new ProgrammerMessage(window,operation==1,journal,title,pages):operation==2?ProgrammerMessage.copy(window):ProgrammerMessage.vehicle(window,operation==4);profile("constructor/"+window+"/"+operation+"/"+journal+"/"+pattern,bytes(message));}
  byte[] empty=bytes(ProgrammerMessage.copy(19));for(int length=0;length<empty.length;length++)profile("truncated/"+length,Arrays.copyOf(empty,length));for(int operation:new int[]{5,127,255}){byte[] wire=empty.clone();wire[4]=(byte)operation;profile("operation/"+operation,wire);}for(int extra:new int[]{1,5})profile("trailing/"+extra,Arrays.copyOf(empty,empty.length+extra));byte[] truth=empty.clone();truth[5]=2;profile("noncanonical-true",truth);
  profile("title-byte-bound",textBody(161,"",false));profile("title-character-bound",textBody(41,String.join("",Collections.nCopies(41,"x")),false));profile("page-byte-bound",textBody(2049,"",true));profile("page-character-bound",textBody(513,String.join("",Collections.nCopies(513,"x")),true));for(int value:new int[]{0,255}){byte[] wire=textBody(1,"x",false);wire[8]=(byte)value;profile("raw-title/"+value,wire);}JsonObject root=new JsonObject();root.addProperty("schema",1);root.add("cases",CASES);StringBuilder golden=new StringBuilder();for(byte value:java.security.MessageDigest.getInstance("SHA-256").digest(root.toString().getBytes(StandardCharsets.UTF_8)))golden.append(String.format(Locale.ROOT,"%02x",value&255));if(CASES.size()!=286||!golden.toString().equals("1ab9e097109d822c9382f571957444293258799e27c41053bb881045a1b8f69a"))throw new AssertionError("Released Programmer wire changed: "+golden);root.addProperty("golden",golden.toString());Path output=Paths.get(System.getProperty("vandorlabs.programmerWireReference","build/test-artifacts/programmer-wire-forge.json"));Files.createDirectories(output.toAbsolutePath().getParent());try(java.io.Writer writer=Files.newBufferedWriter(output)){new Gson().toJson(root,writer);}System.out.println("Actual Programmer wire Source PASS cases="+CASES.size()+" golden="+golden);}
}
